return $input.all().map((item, i) => ({
  json: { ...item.json, _source: 'historico', _index: i }
}));

// Marca a origem de cada linha vinda do formulário de novos clientes
return $input.all().map((item, i) => ({
  json: { ...item.json, _source: 'formulario', _index: i }
}));

// Normaliza linhas das duas abas para um formato único e leve para o front.
// Procura uma chave por aproximação (case-insensitive, ignora acentos/espaços).
function norm(s) {
  return String(s == null ? '' : s)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]/g, '');
}
function pick(row, candidates) {
  const keys = Object.keys(row);
  for (const cand of candidates) {
    const target = norm(cand);
    const hit = keys.find((k) => norm(k) === target);
    if (hit && String(row[hit]).trim() !== '') return String(row[hit]).trim();
  }
  return '';
}
function statusFrom(text) {
  const t = norm(text);
  if (!t) return 'desconhecido';
  if (/(naoaprov|reprov|recus|negad|cancel|perd|nao)/.test(t)) return 'reprovado';
  if (/(aprov|sim|ok|fechad|ganho|aceito|vendid)/.test(t)) return 'aprovado';
  return 'pendente';
}

const out = [];
for (const item of $input.all()) {
  const row = item.json || {};
  // Ignora linhas internas/vazias
  const source = row._source || 'historico';
  const clean = {};
  for (const k of Object.keys(row)) {
    if (k === '_source' || k === '_index' || k === 'row_number') continue;
    clean[k] = row[k];
  }
  // Linha totalmente vazia? pula
  const hasAny = Object.values(clean).some((v) => String(v).trim() !== '');
  if (!hasAny) continue;

  const cliente = pick(row, ['CLIENTE', 'Cliente', 'Empresa', 'Nome da empresa', 'Razao social']);
  const po = pick(row, ['PÓ', 'PO', 'Pó', 'Material', 'Particulado', 'Tipo de pó']);
  const equipamento = pick(row, ['EQUIPAMENTO', 'Equipamento', 'Coletor', 'Modelo']);
  const motor = pick(row, ['MOTOR', 'Motor', 'Potencia', 'Potência']);
  const filtro = pick(row, ['TECIDO', 'Tecido', 'Filtro', 'Midia', 'Mídia', 'Elemento filtrante']);
  const aprovacaoTxt = pick(row, ['APROVAÇÃO', 'APROVACAO', 'Aprovação', 'Status', 'Situacao', 'Resultado']);
  const observacoes = pick(row, ['OBSERVAÇÕES', 'OBSERVACOES', 'Observações', 'Observacao', 'Notas', 'Detalhes']);
  const processo = pick(row, ['PROCESSO', 'Processo', 'Aplicacao', 'Aplicação', 'Maquina', 'Máquina']);

  out.push({
    json: {
      source,
      cliente,
      po,
      processo,
      equipamento,
      motor,
      filtro,
      aprovacao: aprovacaoTxt,
      status: statusFrom(aprovacaoTxt),
      observacoes,
      fields: clean
    }
  });
}
return out;
